from pathlib import Path
import json,hashlib,datetime
R=Path(__file__).resolve().parents[1];Q=R/'reports';P=R.parents[2]/'reconstruction/CatGunnerUnityClient'
def read(n):return json.loads((Q/n).read_text())
runs=[]
for n,key,count in [('short-buff-playmode.json','OriginalShortBuffTests',10),('short-buff-regression-boss.json','OriginalBossSweepTests',8),('short-buff-regression-monster.json','OriginalMonsterSweepTests',9),('short-buff-regression-speed.json','OriginalSpeedRunSweepTests',7),('short-buff-regression-mine.json','OriginalMineSweepTests',7),('short-buff-regression-startup.json','OriginalStartupTests',4)]:
 d=read(n);assert d['status']=='completed' and d['summary']['passed']==d['summary']['total']==count and d['summary']['failed']==0 and all(key in x['FullName'] for x in d['results']),n;runs.append({'report':'reports/'+n,'duration':d['duration'],'summary':d['summary'],'independentCompleteRun':True})
p=read('short-buff-preservation.json');assert p['userMainAndBackupUnchanged'] and p['existingScriptMetasUnchanged']==232 and p['historicalGpuFramesPreserved']==282
h=read('short-buff-editor-handoff.json');assert h['objects']==35954 and h['missingScripts']==0 and h['persist'] and h['timeScale']==1 and h['shortBuffBound'] and h['shortBuffPopupHidden'] and h['shortBuffPanels']==3
assert not any(h[x] for x in ['playing','dirty','compiling','updating','saveFolderOverride','testHostFolder','inputOverrides','mouseFixtures']);assert h['localRewardedAdDefault'] and h['localPurchaseSimulation'] and h['tutorialHudReferences']==10
console=read('short-buff-final-console-status.json')['data']['result']['groundTruth'];assert not console['compilationFailed'] and not console['compiling'] and console['consoleErrors']==0
native=read('short-buff-native-contract.json');assert native['allQueriesCompleted'] and len(native['methods'])==49
visual=[]
for name in ['inactive-popup','super-popup','permanent-popup']:
 f=Q/'visual'/('short-buff-'+name+'-gpu.png');assert f.exists();visual.append({'path':str(f.relative_to(R)),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'actuallyViewed':True})
e={'updatedUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'target':'com.Chodun.CatGunner 1.1.61 vc257','rule':55,'editor':'6000.4.10f1','native':native,'connected':['120 original popup/HUD objects and five original Buff components; original ad/open/close callbacks','Money, damage and speed independent1/3; shared all-active4 and permanent4','Add300/cap900, native scaled clock, pause, expiry fallback and original three-field save reload','Upgrade HUD icons/colors/x3 orx4; mine original placement14 callback and ticket/speed gate','Boss/Monster distinct damage/speed previews and SpeedRun speed calculations','Local ad disabled/cancelled/duplicate/page-revision guards; original permanent pack freezes raw timers'], 'adapters':native['adapters'],'independentTests':runs,'historicalAttempts':['reports/short-buff-before-failure.json','reports/short-buff-first-attempt.json','reports/short-buff-pre-hud-playmode.json','reports/short-buff-hud-before-failure.json','reports/short-buff-before-hud-regression-boss.json'],'gpu':visual,'preservation':p,'handoff':h,'finalConsole':console,'sceneRestoration':read('short-buff-scene-restoration.json'),'layoutRepair':read('short-buff-layout-preservation-repair.json'),'realPaymentCharged':False,'userProgressRestoredOrReset':False,'apkBuilt':False,'deviceAcceptance':False,'gitCommitOrPush':False,'scopeComplete':False,'pending':'Temporary-buff offline simulation formula; temporary guns/ad rebirth; complete I2/UI/services/FreeCash/trusted clock and Buff-popup permanent-pack purchase callback; advanced skeletal deformation/energy meshes/VFX; one remaining tutorial HUD; Player/device acceptance'}
(Q/'short-buff-evidence.json').write_text(json.dumps(e,ensure_ascii=False,indent=2));print({'batches':[r['summary'] for r in runs],'preservedRecords':len(p['records']),'scopeComplete':False})
